import 'package:flutter/material.dart';\n\nclass FavoritesProvider extends ChangeNotifier {\n  final List<String> _favoriteChannelIds = [];\n\n  List<String> get favoriteChannelIds => _favoriteChannelIds;\n\n  void addFavorite(String channelId) {\n    if (!_favoriteChannelIds.contains(channelId)) {\n      _favoriteChannelIds.add(channelId);\n      notifyListeners();\n    }\n  }\n\n  void removeFavorite(String channelId) {\n    _favoriteChannelIds.remove(channelId);\n    notifyListeners();\n  }\n\n  bool isFavorite(String channelId) {\n    return _favoriteChannelIds.contains(channelId);\n  }\n}\n